/* Exactly one byte more than the declared `available` region must be
 * rejected up front, before any flash write is attempted.
 */
ZTEST(lib_stream_flash, test_stream_flash_buffered_write_available_offbyone)
{
	int rc;
	const size_t small_available = 100;

	init_target();

	rc = stream_flash_init(&ctx, fdev, generic_buf, BUF_LEN, FLASH_BASE, small_available,
			       NULL);
	zassert_equal(rc, 0, "expected success");

	rc = stream_flash_buffered_write(&ctx, write_buf, small_available + 1, false);
	zassert_equal(rc, -ENOMEM,
		      "expected -ENOMEM writing one byte past available, got %d", rc);
}
